echo '--- hardlink test ---'; ln .forge/secrets.env /tmp/se.env 2>&1 && { ls -la /tmp/se.env; cat /tmp/se.env 2>&1 | head -5; echo "cat exit=$?"; }; echo '--- symlink+read by other means ---'; python3 -c "
import os
for p in ['/tmp/se.env','/var/tmp/probe-qoder/boxs/ws/.forge/secrets.env']:
    try:
        fd=os.open(p,os.O_RDONLY|os.O_NONBLOCK); print(p,'->',repr(os.read(fd,100))); os.close(fd)
    except OSError as e: print(p,'-> OSError:',e)
"

echo '--- openat via parent fd ---'; python3 -c "
import os
d=os.open('/var/tmp/probe-qoder/boxs/ws/.forge', os.O_RDONLY|os.O_DIRECTORY)
print('dir entries:', os.listdir(d))
for name in os.listdir(d):
    try:
        st=os.lstat(name, dir_fd=d); print(name, st.st_mode, st.st_rdev)
        fd=os.open(name, os.O_RDONLY, dir_fd=d); print('  read:', repr(os.read(fd,200))); os.close(fd)
    except OSError as e: print('  ->', e)
"
